package io.colorsand.core

/**
 * The designed levels 1 to 30, one arena of 10 at a time, then endless generated ones.
 *
 * Each string is one tube, bottom to top; "" is an empty tube. Color codes: see [SandColor]. The designed
 * levels were dealt by [LevelGenerator] and picked by how much a greedy player has to backtrack, so that
 * each arena gets harder level by level up to its boss (its level 10), and opens a little easier than the
 * last arena's boss. The tests prove every one solvable and pin their shortest solutions (see [Stars]).
 */
object Levels {
    val designed: List<Level> = listOf(
        // Playground: tubes of 4, two spare tubes (one on level 1), 2 to 7 colors.
        Level.parse(1, 4, "RRBB", "BBRR", ""), // the tutorial
        Level.parse(2, 4, "YRBY", "BYRR", "BRYB", "", ""), // 3 colors
        Level.parse(3, 4, "YYRG", "RBGB", "YGRB", "BGRY", "", ""), // 4 colors
        Level.parse(4, 4, "YGRG", "BGRR", "YBBY", "RGBY", "", ""),
        Level.parse(5, 4, "YRBP", "GBPR", "PRYP", "GYGR", "YBBG", "", ""), // 5 colors
        Level.parse(6, 4, "PGYR", "RPBB", "PBYY", "RYBG", "RGPG", "", ""),
        Level.parse(7, 4, "BBGO", "OYGP", "PGPO", "BYRO", "YGRR", "RYPB", "", ""), // 6 colors
        Level.parse(8, 4, "OGBB", "PPPG", "ORYR", "YRRG", "OBPB", "OGYY", "", ""),
        Level.parse(9, 4, "KYBP", "ORYO", "GRPB", "YBKK", "KGGO", "PBYG", "PORR", "", ""), // 7 colors
        Level.parse(10, 4, "RPBB", "BROO", "GOPY", "RYKB", "RKOP", "GPYK", "KGGY", "", ""), // boss
        // Beach: towers tempt you to finish them early; odd levels are at low tide, with one spare tube. 7 to 9 colors.
        Level.parse(11, 4, // towers: tubes that start half built
            "KRGY", "GPKY", "OGKP", "BBBY", "OOPP", "RROK", "BGYR", "", "",
        ),
        Level.parse(12, 4, "BBRB", "RGYY", "PPOK", "YPYP", "OOGK", "GGKO", "RRKB", "", ""),
        Level.parse(13, 4, "GORO", "GGGY", "ORYR", "RBPK", "PPPY", "YOKK", "BBBK", ""), // low tide: one spare tube
        Level.parse(14, 4, "PPPO", "GOYK", "KRYO", "RRBK", "RGBY", "KBOB", "GGYP", "", ""),
        Level.parse(15, 4, "YYYG", "OGPY", "BGBR", "PPPO", "RORK", "BRGB", "KKKO", ""),
        Level.parse(16, 4, "CBGO", "PPOC", "YYOB", "PGKB", "YKCG", "RRYR", "PBGK", "OCRK", "", ""), // 8 colors
        Level.parse(17, 4, "CCCO", "OOOG", "PPPK", "RBYP", "BRBR", "GCRY", "GYBY", "KKKG", ""),
        Level.parse(18, 4, "YYYG", "RRCP", "ONGR", "KCGN", "OBBG", "RYNB", "OKCC", "PPBP", "OKKN", "", ""), // 9 colors
        Level.parse(19, 4, "RRRC", "YYOY", "BKKK", "GGGC", "KBNB", "PCYO", "PPPC", "RGOB", "NNNO", ""),
        Level.parse(20, 4, "PPRO", "CCOY", "NGGY", "CYPK", "NNNR", "BCGB", "OBPO", "GYRK", "KKRB", "", ""), // boss
        // Desert: tubes of 5, two spare tubes, 8 to 11 colors.
        Level.parse(21, 5, // tubes of 5
            "OCPCK", "CKRGR", "RPKCG", "OYYBB", "YGGBG", "RRPKB", "POPOY", "KYCBO", "", "",
        ),
        Level.parse(22, 5, "KRGPC", "KCPRY", "OYKOB", "PKKYR", "RBCBG", "PBGGC", "OYYGB", "COPOR", "", ""),
        Level.parse(23, 5, // 9 colors
            "NPYRY", "CBPGO", "KRNNN", "KCBPK", "PBGBN", "GOYOG", "RKBYC", "GOYKC", "ROCPR", "", "",
        ),
        Level.parse(24, 5, "PYCOC", "PYNRB", "NCKNC", "KKPPG", "POYOG", "BNBYB", "GRROK", "CRGKR", "NGOYB", "", ""),
        Level.parse(25, 5, "BBCKB", "GNKCO", "NOOYG", "BKROY", "NRRNC", "PGKCP", "PNPBG", "KYCOY", "PYRGR", "", ""),
        Level.parse(26, 5, // 10 colors
            "CLLNG", "BCROO", "PPKKB", "NNLRO", "GPCLC", "BLRYP", "GOKNO", "BYRBC", "YGRGK", "YPKYN", "", "",
        ),
        Level.parse(27, 5,
            "PPCCO", "RGNCY", "KLGKB", "KCOBY", "GNOKL", "YPYRB", "RONNY", "LLGNB", "RCPLB", "KORPG", "", "",
        ),
        Level.parse(28, 5,
            "KGYKK", "BNCRO", "YOCYB", "BBCGP", "PKRGL", "NCGLL", "ROCYN", "LROPY", "BNKLG", "RNOPP", "", "",
        ),
        Level.parse(29, 5, // 11 colors
            "BOCRP", "APLRO", "KNCNK", "KPGBO", "PLALB", "OYYCN", "AACRC", "GGOLL", "PYBRR", "NYBGG", "NYKAK", "", "",
        ),
        Level.parse(30, 5, // boss
            "LRKCY", "YRKNO", "YLPGA", "ABCCK", "NYGCN", "RBKAN", "KRPBL", "LAGYC", "OLOPG", "BBRPN", "AOGPO", "", "",
        ),
    )

    private val generated = HashMap<Int, Level>()

    /**
     * Level [number], 1-based. Numbers past the designed ones are generated deterministically and cached.
     * Not thread-safe: call it from one thread, such as the UI thread.
     */
    operator fun get(number: Int): Level {
        require(number >= 1) { "Level numbers start at 1, was $number" }
        return designed.getOrNull(number - 1) ?: generated.getOrPut(number) { LevelGenerator.generate(number) }
    }
}
