package io.colorsand.ui

import androidx.compose.ui.graphics.Color
import io.colorsand.core.SandColor
import kotlin.math.PI
import kotlin.math.cos
import kotlin.math.pow
import kotlin.math.roundToInt
import kotlin.math.sin

/**
 * How the nine colorful sands sit around the color wheel. [offsets] are hue angles in degrees relative to the
 * scheme's [CustomScheme.hue], one per entry of [CustomScheme.CHROMATIC]. The three lightness steps repeat
 * every three slots, so the sands that share a lightness always form a triad (120 degrees apart) and the
 * ones next to each other on the wheel differ in lightness as well as in hue.
 */
enum class Harmony(val key: String, val label: String, val offsets: List<Float>) {
    /** Nine hues 40 degrees apart: a full rainbow. */
    RAINBOW("rainbow", "Rainbow", List(9) { it * 40f }),

    /** Three families of three, 120 degrees apart, each a small analogous group. */
    TRIADS("triads", "Triads", listOf(-25f, 0f, 25f, 95f, 120f, 145f, 215f, 240f, 265f)),

    /** A run of five analogous hues and four across the wheel from them: complementary families. */
    PAIRS("pairs", "Pairs", listOf(-50f, -25f, 0f, 25f, 50f, 142.5f, 167.5f, 192.5f, 217.5f)),
}

/**
 * The player's own palette: a [harmony] turned to [hue] degrees, at [saturation] (0 = calmest, 1 = most vivid).
 * Values are kept on a 1 degree / 1 percent grid so that what is stored is exactly what was shown.
 */
data class CustomScheme(val harmony: Harmony, val hue: Int, val saturation: Int) {
    init {
        require(hue in 0 until 360) { "hue $hue" }
        require(saturation in 0..100) { "saturation $saturation" }
    }

    /** Hue of the chromatic sand in [slot] (an index into [CHROMATIC]), in [0, 360). */
    fun hueOf(slot: Int): Float = wrap(hue + harmony.offsets[slot])

    /**
     * The scheme after the dot of [slot] is dragged to [angle] degrees at [radius] (0 = inner edge of the ring,
     * 1 = outer edge): every hue turns by the same amount so the harmony keeps its shape, and the distance from
     * the centre sets the shared saturation.
     */
    fun drag(slot: Int, angle: Float, radius: Float): CustomScheme = CustomScheme(
        harmony,
        hue = wrap(angle - harmony.offsets[slot]).roundToInt() % 360,
        saturation = (radius.coerceIn(0f, 1f) * 100).roundToInt(),
    )

    /**
     * The scheme turned by [hueBy] degrees and with [saturationBy] percent more saturation, kept in range: the
     * steps behind the wheel's arrow keys and screen-reader actions.
     */
    fun nudge(hueBy: Int = 0, saturationBy: Int = 0): CustomScheme =
        copy(hue = ((hue + hueBy) % 360 + 360) % 360, saturation = (saturation + saturationBy).coerceIn(0, 100))

    /** Small text form for [ProgressStore.customColors], e.g. "rainbow 25 60". */
    fun encode(): String = "${harmony.key} $hue $saturation"

    /** The full [Palette]: sand colors plus a night sky and UI colors tinted to match. */
    fun palette(): Palette {
        val s = saturation / 100f
        val chroma = MIN_CHROMA + s * (MAX_CHROMA - MIN_CHROMA)
        val colors = HashMap<SandColor, Color>()
        CHROMATIC.forEachIndexed { slot, sand -> colors[sand] = oklch(LIGHTNESS[slot % 3], chroma, hueOf(slot)) }
        // The neutrals keep their roles (deep, middle, light) and take on a faint tint of the scheme.
        colors[SandColor.BROWN] = oklch(0.46f, 0.06f, hue + 40f)
        colors[SandColor.GRAY] = oklch(0.655f, 0.015f, hue + 250f)
        colors[SandColor.WHITE] = oklch(0.96f, 0.012f, hue + 60f)
        // At the default hue these land near Classic: a navy-to-violet sky, cream titles, yellow hints, green done.
        val sky = 0.025f + 0.02f * s
        val text = oklch(0.97f, 0.01f, hue + 60f)
        val top = oklch(0.22f, sky, hue + 250f)
        return Palette(
            name = NAME,
            sand = { colors.getValue(it) },
            backgroundTop = top,
            backgroundBottom = oklch(0.29f, sky + 0.01f, hue + 290f),
            accent = oklch(0.93f, 0.045f, hue + 60f),
            onAccent = top,
            highlight = oklch(0.86f, 0.14f, hue + 70f),
            done = oklch(0.8f, 0.13f, hue + 110f),
            surface = oklch(0.27f, sky, hue + 260f),
            text = text,
            dimText = text.copy(alpha = 0.7f),
        )
    }

    companion object {
        const val NAME = "Custom"

        /** The colorful sands in wheel order; at the default hue they sit close to their names. */
        val CHROMATIC = listOf(
            SandColor.RED, SandColor.ORANGE, SandColor.YELLOW, SandColor.LIME, SandColor.GREEN,
            SandColor.CYAN, SandColor.BLUE, SandColor.PURPLE, SandColor.PINK,
        )

        /** Dark, middle and light step, repeating along [CHROMATIC]. */
        val LIGHTNESS = floatArrayOf(0.57f, 0.70f, 0.83f)

        /** OKLCH chroma at saturation 0 and 100. Below the minimum, neighbors on the wheel start to blur. */
        const val MIN_CHROMA = 0.13f
        const val MAX_CHROMA = 0.22f

        val Default = CustomScheme(Harmony.RAINBOW, hue = 25, saturation = 60)

        /** Reads [encode]'s form; anything it can't make sense of gives [Default]. */
        fun decode(text: String?): CustomScheme {
            val parts = text?.trim()?.split(' ')?.filter { it.isNotEmpty() } ?: return Default
            if (parts.size != 3) return Default
            val harmony = Harmony.entries.firstOrNull { it.key == parts[0] } ?: return Default
            val hue = parts[1].toIntOrNull()?.takeIf { it in 0 until 360 } ?: return Default
            val saturation = parts[2].toIntOrNull()?.takeIf { it in 0..100 } ?: return Default
            return CustomScheme(harmony, hue, saturation)
        }

        private fun wrap(degrees: Float): Float = ((degrees % 360f) + 360f) % 360f
    }
}

/** The palette [store] asks for: a built-in one by name, or the player's [CustomScheme]. */
fun storedPalette(store: ProgressStore): Palette =
    if (store.palette == CustomScheme.NAME) CustomScheme.decode(store.customColors).palette()
    else Palettes.byName(store.palette)

/**
 * The sRGB color at OKLCH lightness [l], chroma [c] and hue [h] degrees. Where that chroma is out of the sRGB
 * gamut, it is reduced until the color fits, so hue and lightness stay put.
 */
fun oklch(l: Float, c: Float, h: Float): Color {
    val rad = h * PI / 180
    val ca = cos(rad)
    val sa = sin(rad)
    fun rgb(chroma: Double): DoubleArray = oklabToLinear(l.toDouble(), chroma * ca, chroma * sa)
    fun fits(v: DoubleArray) = v.all { it in -1e-4..1.0001 }
    var lo = 0.0
    if (fits(rgb(c.toDouble()))) lo = c.toDouble() else {
        var hi = c.toDouble()
        repeat(20) {
            val mid = (lo + hi) / 2
            if (fits(rgb(mid))) lo = mid else hi = mid
        }
    }
    val v = rgb(lo)
    return Color(encodeSrgb(v[0]), encodeSrgb(v[1]), encodeSrgb(v[2]))
}

private fun oklabToLinear(l: Double, a: Double, b: Double): DoubleArray {
    val l1 = (l + 0.3963377774 * a + 0.2158037573 * b).pow(3)
    val m1 = (l - 0.1055613458 * a - 0.0638541728 * b).pow(3)
    val s1 = (l - 0.0894841775 * a - 1.2914855480 * b).pow(3)
    return doubleArrayOf(
        4.0767416621 * l1 - 3.3077115913 * m1 + 0.2309699292 * s1,
        -1.2684380046 * l1 + 2.6097574011 * m1 - 0.3413193965 * s1,
        -0.0041960863 * l1 - 0.7034186147 * m1 + 1.7076147010 * s1,
    )
}

private fun encodeSrgb(linear: Double): Float {
    val c = linear.coerceIn(0.0, 1.0)
    return (if (c <= 0.0031308) 12.92 * c else 1.055 * c.pow(1 / 2.4) - 0.055).toFloat()
}
