package io.colorsand.core

/**
 * Finds short solutions, for pars and hints. [Solver] finds *a* solution fast; this looks for one a careful
 * player would find.
 *
 * It is a best-first search on moves made plus a lower bound of the moves still needed ([remaining]),
 * with the bound weighted by [weight]: weight 1 is A*, which proves the solution is the shortest; a higher
 * weight finds a near-shortest one much faster. The search stops after [maxStates] boards and then answers
 * with the best solution found so far, or null if there is none yet.
 */
object Planner {
    const val DEFAULT_MAX_STATES = 20_000
    const val DEFAULT_WEIGHT = 2

    fun plan(board: Board, maxStates: Int = DEFAULT_MAX_STATES, weight: Int = DEFAULT_WEIGHT): List<Move>? {
        if (board.isSolved) return emptyList()
        // A node is a board, the move that reached it and its parent; following parents gives the path.
        class Node(val board: Board, val move: Move?, val parent: Node?, val depth: Int)

        val bestDepth = HashMap<Any, Int>()
        val queue = BucketQueue<Node>()
        val start = Node(board, null, null, 0)
        bestDepth[Solver.key(board)] = 0
        queue.add(weight * remaining(board), start)
        var best: Node? = null
        var expanded = 0
        while (true) {
            val node = queue.poll() ?: break
            val found = best
            // With weight 1, once nothing left in the queue can beat the solution found, it is the shortest.
            // A higher weight takes the first solution it finds.
            if (found != null && (weight > 1 || node.depth + remaining(node.board) >= found.depth)) break
            if (node.depth > (bestDepth[Solver.key(node.board)] ?: Int.MAX_VALUE)) continue
            if (++expanded > maxStates) break
            for (move in Solver.usefulMoves(node.board)) {
                val next = node.board.pour(move.from, move.to)!!.first
                val depth = node.depth + 1
                val left = remaining(next)
                if (found != null && depth + left >= found.depth) continue
                val key = Solver.key(next)
                if (depth >= (bestDepth[key] ?: Int.MAX_VALUE)) continue
                bestDepth[key] = depth
                val child = Node(next, move, node, depth)
                if (next.isSolved) {
                    best = child
                    continue
                }
                queue.add(depth + weight * left, child)
            }
        }
        val end = best ?: return null
        return generateSequence(end) { it.parent }.mapNotNull { it.move }.toList().reversed()
    }

    /**
     * A lower bound on the pours still needed: every pour removes at most one run of color from the board,
     * and a solved board has one run per color.
     */
    fun remaining(board: Board): Int {
        var runs = 0
        val colors = HashSet<SandColor>()
        for (tube in board.tubes) {
            var previous: SandColor? = null
            for (color in tube.layers) {
                if (color != previous) runs++
                previous = color
                colors.add(color)
            }
        }
        return runs - colors.size
    }

    /** A priority queue for small non-negative int priorities, lowest first, first in first out within one. */
    private class BucketQueue<T> {
        private val buckets = ArrayList<ArrayDeque<T>>()
        private var lowest = 0
        private var size = 0

        fun add(priority: Int, item: T) {
            while (buckets.size <= priority) buckets.add(ArrayDeque())
            buckets[priority].addLast(item)
            if (priority < lowest) lowest = priority
            size++
        }

        fun poll(): T? {
            if (size == 0) return null
            while (buckets[lowest].isEmpty()) lowest++
            size--
            return buckets[lowest].removeFirst()
        }
    }
}
