package io.colorsand.ui.arena

import androidx.compose.foundation.layout.Spacer
import androidx.compose.runtime.Composable
import androidx.compose.runtime.State
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.drawWithCache
import androidx.compose.ui.geometry.CornerRadius
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.Rect
import androidx.compose.ui.geometry.Size
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Path
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.drawscope.DrawScope
import androidx.compose.ui.graphics.drawscope.Stroke
import androidx.compose.ui.graphics.drawscope.rotate
import androidx.compose.ui.graphics.drawscope.scale
import androidx.compose.ui.graphics.drawscope.translate
import androidx.compose.ui.graphics.lerp
import kotlin.math.abs
import kotlin.math.min

/**
 * The Playground: a sunny morning park. A blue sky with a warm sun in the corner, drifting clouds, pale hills
 * far away, a swing set and a slide on the green hill, trees swaying at the sides, and the wooden sandbox the
 * game is played in along the bottom. A butterfly wanders over the grass.
 */
@Composable
internal fun PlaygroundScene(grade: SceneGrade, modifier: Modifier = Modifier) {
    val clock = rememberSceneClock()
    Spacer(
        modifier.drawWithCache {
            val art = PlaygroundArt(size, grade)
            onDrawBehind { art.draw(this, clock) }
        },
    )
}

/** Everything the Playground draws, built once per size and grade; [draw] only moves it. */
private class PlaygroundArt(size: Size, private val g: SceneGrade) {
    private val w = size.width
    private val h = size.height

    /** The size unit for things in the scene, so they keep their shape on wide and tall screens. */
    private val u = min(w, h * 0.6f)

    private val horizon = Color(0xFFE8F6F0)
    private fun far(c: Long, amount: Float) = g(lerp(Color(c), horizon, amount))

    private val sky = Brush.verticalGradient(
        0f to g(0xFF3A93DB), 0.32f to g(0xFF66B4EA), 0.58f to g(0xFFA6D8F2), 0.72f to g(horizon),
        startY = 0f, endY = h,
    )

    // Sun in the top-left corner.
    private val sunCenter = Offset(w * 0.1f, h * 0.055f)
    private val sunCore = g(0xFFFFF8DC)
    private val sunGlow = g(0xFFFFE9A3)
    private val ray = Path().apply {
        moveTo(0f, -u * 0.02f)
        lineTo(u * 0.7f, -u * 0.06f)
        lineTo(u * 0.7f, u * 0.06f)
        lineTo(0f, u * 0.02f)
        close()
    }
    private val rayBrush = Brush.horizontalGradient(
        0f to g(Color(0x24FFF4C8)), 1f to Color.Transparent, startX = 0f, endX = u * 0.7f,
    )

    // Clouds: far small ones drift slowly, near big ones twice as fast.
    private class Cloud(val path: Path, val y: Float, val width: Float, val start: Float, val laps: Int, val alpha: Float)

    private val clouds = SceneRandom(7).let { r ->
        listOf(
            Cloud(cloudPath(u * 0.18f, 4, r), h * 0.215f, u * 0.18f, 0.15f, 1, 0.6f),
            Cloud(cloudPath(u * 0.24f, 5, r), h * 0.17f, u * 0.24f, 0.62f, 1, 0.7f),
            Cloud(cloudPath(u * 0.34f, 6, r), h * 0.11f, u * 0.34f, 0.35f, 2, 0.88f),
            Cloud(cloudPath(u * 0.3f, 5, r), h * 0.06f, u * 0.3f, 0.88f, 2, 0.85f),
        )
    }
    private val cloudWhite = g(0xFFFFFFFF)
    private val cloudShade = g(0xFFC9DDF0)

    // Hills, far to near: farther is paler and bluer.
    private val farRidge = Ridge(w, h * 0.735f, h * 0.06f, 1.2f, 0.1f)
    private val farHill = farRidge.fill(h)
    private val farBrush = Brush.verticalGradient(
        0f to far(0xFF8CC9A0, 0.42f), 1f to far(0xFF7DBF8E, 0.32f), startY = h * 0.67f, endY = h * 0.78f,
    )
    private val farTrees = SceneRandom(3).let { r ->
        List(9) {
            val x = w * (0.05f + 0.9f * r.next())
            val radius = u * r.next(0.01f, 0.017f)
            Offset(x, farRidge.y(x) + radius * 0.4f) to radius
        }
    }
    private val farTree = far(0xFF5FA570, 0.38f)
    private val nearFarRidge = Ridge(w, h * 0.765f, h * 0.045f, 1.7f, 0.55f)
    private val nearFarHill = nearFarRidge.fill(h)
    private val nearFarBrush = Brush.verticalGradient(
        0f to far(0xFF86C77C, 0.38f), 1f to far(0xFF73B86C, 0.3f), startY = h * 0.71f, endY = h * 0.8f,
    )

    private val midRidge = Ridge(w, h * 0.815f, h * 0.045f, 0.9f, 0.3f)
    private val midHill = midRidge.fill(h)
    private val midLine = midRidge.line()
    private val midBrush = Brush.verticalGradient(
        0f to far(0xFF7CC55B, 0.12f), 1f to g(0xFF5DA746), startY = h * 0.76f, endY = h * 0.88f,
    )
    private val midRim = g(Color(0xAAC5EC97))

    // Swing set on the left, slide on the right, both standing on the green hill.
    private val swingX = w * 0.15f
    private val swingBase = midRidge.y(swingX + u * 0.09f) + u * 0.012f
    private val swingFrame = far(0xFFD2553F, 0.22f)
    private val swingSeat = far(0xFF8A5A3C, 0.22f)
    private val slideX = w * 0.84f
    private val slideBase = midRidge.y(slideX) + u * 0.012f
    private val slideChute = far(0xFFF4B740, 0.18f)
    private val slideChuteDark = far(0xFFD8922A, 0.18f)
    private val slideRail = far(0xFF4C8FC4, 0.22f)

    // Trees at both sides.
    private class Tree(val x: Float, val base: Float, val size: Float, val phase: Float)

    private val trees = listOf(
        Tree(w * 0.035f, midRidge.y(w * 0.035f) + u * 0.02f, u * 0.11f, 0f),
        Tree(w * 0.965f, midRidge.y(w * 0.965f) + u * 0.02f, u * 0.125f, 0.4f),
    )
    private val canopy = Path().apply {
        addOval(Rect(Offset(0f, -1.05f), 0.62f))
        addOval(Rect(Offset(-0.5f, -0.78f), 0.46f))
        addOval(Rect(Offset(0.52f, -0.8f), 0.48f))
        addOval(Rect(Offset(0.05f, -1.5f), 0.46f))
    }
    private val canopyLight = Path().apply {
        addOval(Rect(Offset(-0.12f, -1.18f), 0.42f))
        addOval(Rect(Offset(-0.48f, -0.9f), 0.28f))
        addOval(Rect(Offset(0.0f, -1.6f), 0.3f))
    }
    private val leafDark = far(0xFF3E8A3F, 0.1f)
    private val leafLight = far(0xFF6FC05A, 0.1f)
    private val trunk = far(0xFF7A5134, 0.1f)

    // Grass in front, with tufts and a few flowers.
    private val grassRidge = Ridge(w, h * 0.84f, h * 0.025f, 0.7f, 0.65f)
    private val grass = grassRidge.fill(h)
    private val grassBrush = Brush.verticalGradient(
        0f to g(0xFF6BBB4F), 1f to g(0xFF4C9A3D), startY = h * 0.8f, endY = h * 0.88f,
    )
    private val tufts = Path().apply {
        val r = SceneRandom(11)
        var x = 0f
        while (x < w) {
            val y = grassRidge.y(x) + u * r.next(0.004f, 0.03f)
            val s = u * r.next(0.012f, 0.022f)
            moveTo(x - s * 0.5f, y); lineTo(x - s * 0.7f, y - s)
            moveTo(x, y); lineTo(x + s * 0.1f, y - s * 1.3f)
            moveTo(x + s * 0.5f, y); lineTo(x + s * 0.8f, y - s * 0.9f)
            x += u * r.next(0.03f, 0.07f)
        }
    }
    private val tuftColor = g(0xFF3F8A35)
    private val flowers = SceneRandom(5).let { r ->
        List(10) {
            val x = w * r.next()
            Offset(x, grassRidge.y(x) + u * r.next(0.01f, 0.035f)) to (if (it % 3 == 0) g(0xFFFFD54F) else g(0xFFFFFFFF))
        }
    }
    private val flowerHeart = g(0xFFF5A623)

    // The sandbox: a wooden frame with sand inside, across the bottom. Its back plank sits just above the
    // controls strip, so the strip rests in the sand.
    private val frameTop = h * 0.85f
    private val plank = u * 0.028f
    private val woodTop = g(0xFFDDA567)
    private val woodFace = g(0xFFB97B45)
    private val woodDark = g(0xFF8E5A31)
    private val sandBrush = Brush.verticalGradient(
        0f to g(0xFFD7B07A), 0.12f to g(0xFFEED4A0), 1f to g(0xFFE4C188),
        startY = frameTop + plank, endY = h,
    )
    private val sideLeft = Path().apply {
        moveTo(w * 0.03f, frameTop); lineTo(w * 0.03f + plank * 1.2f, frameTop)
        lineTo(-w * 0.02f + plank * 1.6f, h); lineTo(-w * 0.02f, h); close()
    }
    private val sideRight = Path().apply {
        moveTo(w * 0.97f, frameTop); lineTo(w * 0.97f - plank * 1.2f, frameTop)
        lineTo(w * 1.02f - plank * 1.6f, h); lineTo(w * 1.02f, h); close()
    }
    private val grain = Path().apply {
        val r = SceneRandom(19)
        repeat(7) {
            val x = w * r.next(0.05f, 0.9f)
            val y = frameTop + plank * r.next(0.35f, 0.8f)
            moveTo(x, y)
            quadraticTo(x + u * 0.06f, y - plank * 0.12f, x + u * r.next(0.08f, 0.16f), y + plank * 0.05f)
        }
    }
    private val sandMounds = SceneRandom(23).let { r ->
        List(4) { Offset(w * r.next(0.1f, 0.9f), h * r.next(0.95f, 0.99f)) to u * r.next(0.08f, 0.14f) }
    }
    private val moundLight = g(Color(0x66FFF0CC))
    private val bucketX = w * 0.075f
    private val bucket = Path().apply {
        val s = u * 0.045f
        moveTo(-s * 0.5f, -s); lineTo(s * 0.5f, -s); lineTo(s * 0.38f, 0f); lineTo(-s * 0.38f, 0f); close()
    }
    private val bucketRed = g(0xFFE6533F)
    private val bucketRim = g(0xFFFF8A6B)

    // The butterfly.
    private val wingA = g(0xFFFF9F43)
    private val wingB = g(0xFFFFD166)
    private val body = g(0xFF4A3426)

    private val shade = vignette(w, h, g(Color(0x40183456)))

    fun draw(scope: DrawScope, clock: State<Float>) = with(scope) {
        val t = clock.value
        drawRect(sky)

        // Sun: glow, slowly turning rays, core.
        drawGlow(sunCenter, u * 0.9f, sunGlow.copy(alpha = 0.55f))
        rotate(t * 30f, sunCenter) {
            for (i in 0 until 12) {
                rotate(i * 30f, sunCenter) { translate(sunCenter.x, sunCenter.y) { drawPath(ray, rayBrush) } }
            }
        }
        drawGlow(sunCenter, u * 0.16f, sunCore)
        drawCircle(sunCore, u * 0.065f, sunCenter)

        for (c in clouds) {
            val x = -c.width + drift(t, c.laps, c.start) * (w + 2 * c.width)
            translate(x, c.y) {
                translate(0f, c.width * 0.05f) { drawPath(c.path, cloudShade, alpha = c.alpha * 0.8f) }
                drawPath(c.path, cloudWhite, alpha = c.alpha)
            }
        }

        drawPath(farHill, farBrush)
        for ((p, r) in farTrees) drawCircle(farTree, r, p)
        drawPath(nearFarHill, nearFarBrush)
        drawPath(midHill, midBrush)
        drawPath(midLine, midRim, style = Stroke(u * 0.006f))

        drawSwingSet(t)
        drawSlide()
        for (tree in trees) drawTree(tree, t)

        drawPath(grass, grassBrush)
        drawPath(tufts, tuftColor, style = Stroke(u * 0.005f, cap = StrokeCap.Round))
        for ((p, color) in flowers) {
            val r = u * 0.007f
            for (k in 0 until 4) drawCircle(color, r, p + Offset(if (k % 2 == 0) r else -r, if (k < 2) r * 0.6f else -r * 0.6f))
            drawCircle(flowerHeart, r * 0.7f, p)
        }

        drawSandbox()
        drawButterfly(t)
        drawRect(shade)
    }

    private fun DrawScope.drawSwingSet(t: Float) {
        val s = u * 0.2f
        val top = swingBase - s * 0.62f
        val stroke = u * 0.011f
        for (leg in listOf(swingX, swingX + s)) {
            drawLine(swingFrame, Offset(leg - s * 0.09f, swingBase), Offset(leg, top), stroke, StrokeCap.Round)
            drawLine(swingFrame, Offset(leg + s * 0.09f, swingBase), Offset(leg, top), stroke, StrokeCap.Round)
        }
        drawLine(swingFrame, Offset(swingX - s * 0.03f, top), Offset(swingX + s * 1.03f, top), stroke * 1.2f, StrokeCap.Round)
        for ((i, x) in listOf(swingX + s * 0.33f, swingX + s * 0.67f).withIndex()) {
            val angle = swing(t, 14, i * 0.3f) * (if (i == 0) 9f else 4f)
            rotate(angle, Offset(x, top)) {
                val seatY = top + s * 0.45f
                drawLine(swingSeat, Offset(x - s * 0.05f, top), Offset(x - s * 0.05f, seatY), u * 0.003f)
                drawLine(swingSeat, Offset(x + s * 0.05f, top), Offset(x + s * 0.05f, seatY), u * 0.003f)
                drawRoundRect(swingSeat, Offset(x - s * 0.08f, seatY - u * 0.004f), Size(s * 0.16f, u * 0.012f), CornerRadius(u * 0.004f))
            }
        }
    }

    private fun DrawScope.drawSlide() {
        val s = u * 0.2f
        val top = slideBase - s * 0.55f
        val ladder = slideX + s * 0.12f
        val stroke = u * 0.009f
        // The chute sweeps down to the left from the platform.
        val chute = Path().apply {
            moveTo(ladder - s * 0.12f, top)
            cubicTo(ladder - s * 0.4f, top + s * 0.05f, ladder - s * 0.55f, slideBase - s * 0.06f, ladder - s * 0.9f, slideBase - s * 0.02f)
        }
        drawPath(chute, slideChuteDark, style = Stroke(u * 0.03f, cap = StrokeCap.Round))
        drawPath(chute, slideChute, style = Stroke(u * 0.018f, cap = StrokeCap.Round))
        drawLine(slideRail, Offset(ladder - s * 0.12f, top), Offset(ladder - s * 0.12f, slideBase), stroke, StrokeCap.Round)
        drawLine(slideRail, Offset(ladder + s * 0.04f, top - s * 0.1f), Offset(ladder + s * 0.08f, slideBase), stroke, StrokeCap.Round)
        drawLine(slideRail, Offset(ladder - s * 0.14f, top - s * 0.1f), Offset(ladder - s * 0.12f, slideBase), stroke, StrokeCap.Round)
        for (k in 1..4) {
            val y = top + (slideBase - top) * k / 5f
            drawLine(slideRail, Offset(ladder - s * 0.12f, y), Offset(ladder + s * 0.05f + s * 0.04f * k / 5f, y), stroke * 0.7f)
        }
        drawLine(slideChute, Offset(ladder - s * 0.16f, top), Offset(ladder + s * 0.06f, top), stroke * 1.4f, StrokeCap.Round)
    }

    private fun DrawScope.drawTree(tree: Tree, t: Float) {
        val s = tree.size
        drawOval(Color.Black.copy(alpha = 0.12f), Offset(tree.x - s * 0.7f, tree.base - s * 0.08f), Size(s * 1.4f, s * 0.2f))
        drawRoundRect(trunk, Offset(tree.x - s * 0.1f, tree.base - s * 0.85f), Size(s * 0.2f, s * 0.85f), CornerRadius(s * 0.08f))
        val pivot = Offset(tree.x, tree.base - s * 0.6f)
        rotate(swing(t, 10, tree.phase) * 1.6f, pivot) {
            translate(tree.x, tree.base - s * 0.45f) {
                scale(s, s, Offset.Zero) {
                    drawPath(canopy, leafDark)
                    translate(swing(t, 13, tree.phase) * 0.02f, 0f) { drawPath(canopyLight, leafLight) }
                }
            }
        }
    }

    private fun DrawScope.drawSandbox() {
        drawRect(sandBrush, Offset(0f, frameTop + plank), Size(w, h - frameTop - plank))
        for ((p, r) in sandMounds) drawOval(moundLight, p - Offset(r, r * 0.18f), Size(r * 2, r * 0.36f))
        // Back plank: a lit top face over the front face.
        drawRect(woodFace, Offset(0f, frameTop), Size(w, plank))
        drawRect(woodTop, Offset(0f, frameTop - plank * 0.35f), Size(w, plank * 0.4f))
        drawPath(grain, woodDark.copy(alpha = 0.5f), style = Stroke(u * 0.002f, cap = StrokeCap.Round))
        drawRect(Color.Black.copy(alpha = 0.1f), Offset(0f, frameTop + plank), Size(w, plank * 0.35f))
        drawPath(sideLeft, woodFace)
        drawPath(sideRight, woodFace)
        for (x in listOf(w * 0.03f + plank * 0.6f, w * 0.97f - plank * 0.6f)) {
            drawRoundRect(woodTop, Offset(x - plank * 0.8f, frameTop - plank * 0.7f), Size(plank * 1.6f, plank * 0.9f), CornerRadius(plank * 0.2f))
        }
        // A red bucket in the corner.
        translate(bucketX, frameTop + (h - frameTop) * 0.6f) {
            drawPath(bucket, bucketRed)
            drawRect(bucketRim, Offset(-u * 0.024f, -u * 0.047f), Size(u * 0.048f, u * 0.007f))
        }
    }

    private fun DrawScope.drawButterfly(t: Float) {
        val x = w * (0.5f + 0.43f * swing(t, 2)) + u * 0.04f * swing(t, 9, 0.2f)
        val y = h * 0.8f + h * 0.02f * swing(t, 7, 0.1f) + u * 0.01f * swing(t, 31)
        val flap = 0.25f + 0.75f * abs(swing(t, 330))
        val s = u * 0.022f
        // Heading left or right with the big swing.
        val facing = if (swing(t, 2, 0.25f) > 0) -1f else 1f
        translate(x, y) {
            scale(flap * facing, 1f, Offset.Zero) {
                drawOval(wingA, Offset(0f, -s * 1.1f), Size(s * 1.2f, s * 1.1f))
                drawOval(wingB, Offset(0f, -s * 0.15f), Size(s * 0.85f, s * 0.75f))
                drawOval(wingA, Offset(-s * 1.2f, -s * 1.1f), Size(s * 1.2f, s * 1.1f))
                drawOval(wingB, Offset(-s * 0.85f, -s * 0.15f), Size(s * 0.85f, s * 0.75f))
            }
            drawLine(body, Offset(0f, -s * 0.8f), Offset(0f, s * 0.5f), s * 0.22f, StrokeCap.Round)
        }
    }
}
