package io.colorsand.ui

import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.BoxWithConstraints
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.Row
import androidx.compose.foundation.layout.padding
import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.runtime.remember
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.layout.onGloballyPositioned
import androidx.compose.ui.unit.dp
import io.colorsand.ui.fx.rejectShake
import io.colorsand.ui.arena.LocalArena
import io.colorsand.ui.arena.tubeStand
import kotlin.math.ceil
import kotlin.math.min

/** All tubes of the current board, laid out in rows and sized to fit. A paw holds the selected tube; each pour plays [pours]. */
@Composable
fun BoardView(game: GameController, modifier: Modifier, pours: PourAnimation = rememberPourAnimation(game)) {
    val tubes = game.board.tubes
    val event = game.lastPour
    val hold = rememberPawHold(game)
    val arena = LocalArena.current
    LaunchedEffect(event) { if (event != null && pours.pour == event) pours.play(event) }
    LaunchedEffect(game.selected) { hold.follow(game.selected) }
    val pour = pours.pour
    // Taken while composing, before the paw lets go of the tube, so the pour carries on from where the paw was.
    val grabbed = remember(pour?.id) { pour?.let { hold.grabbed(it.move.from) } ?: 1f }
    // A tap while sand is still running finishes the pour at once and then counts as usual.
    val tap = { i: Int -> pours.finish(); game.tap(i) }
    BoxWithConstraints(modifier.onGloballyPositioned(pours::placeBoard), contentAlignment = Alignment.Center) {
        val rows = boardRows(tubes.size, maxWidth.value, maxHeight.value)
        val perRow = ceil(tubes.size / rows.toFloat()).toInt()
        val tubeWidth = tubeWidthFor(tubes.size, rows, maxWidth.value, maxHeight.value).dp
        // Headroom over the top row for a tube the paw lifts, so it never reaches into the header.
        Column(Modifier.padding(top = tubeWidth * LIFT_ROOM), verticalArrangement = Arrangement.spacedBy(tubeWidth * 0.7f)) {
            tubes.indices.chunked(perRow).forEach { row ->
                Row(
                    Modifier.tubeStand(arena, row.size, tubeWidth, tubeWidth * 0.4f),
                    horizontalArrangement = Arrangement.spacedBy(tubeWidth * 0.4f),
                ) {
                    for (i in row) {
                        val isTarget = pour?.move?.to == i
                        TubeView(
                            // The target fills up from what it held before the pour.
                            tube = if (isTarget) pour!!.before.tubes[i] else tubes[i],
                            highlight = highlightOf(game, i),
                            width = tubeWidth,
                            onTap = { tap(i) },
                            modifier = Modifier.rejectShake(game.lastRejected, i).onGloballyPositioned { pours.placeTube(i, it) },
                            pouring = if (isTarget) PouringSand(pour!!.color) { pour.move.amount * landed(pours.progress) } else null,
                            hidden = pour?.move?.from == i || hold.shown == i,
                        )
                    }
                }
            }
        }
        HoldOverlay(hold, pours, game.board, game.selected, tubeWidth, onTap = tap)
        PourOverlay(pours, game.board, tubeWidth, grabbed, onTap = tap)
    }
}

/** One row for up to 6 tubes, then as many rows as needed for at most 7 per row. */
internal fun rowCount(tubes: Int): Int = if (tubes <= 6) 1 else ceil(tubes / 7f).toInt().coerceAtLeast(2)

/**
 * The rows for [tubes] on a board [width] x [height] dp: the usual [rowCount], or fewer when that makes the tubes
 * no smaller, as on a wide, short screen.
 */
internal fun boardRows(tubes: Int, width: Float, height: Float): Int {
    val usual = rowCount(tubes)
    val best = tubeWidthFor(tubes, usual, width, height)
    return (1..usual).first { tubeWidthFor(tubes, it, width, height) >= best }
}

/**
 * How wide (dp) each tube is with [tubes] in [rows] rows on a board [width] x [height] dp: each gets a column of
 * the width, each row leaves room for the gap, and the top row headroom for a lifted tube; never more than 64.
 */
internal fun tubeWidthFor(tubes: Int, rows: Int, width: Float, height: Float): Float {
    val perRow = ceil(tubes / rows.toFloat())
    val byWidth = width / perRow * 0.68f
    val byHeight = height / (rows * (TUBE_ASPECT + 0.9f) + LIFT_ROOM)
    return min(min(byWidth, byHeight), 64f)
}

private fun highlightOf(game: GameController, tube: Int): TubeHighlight = when {
    game.selected == tube -> TubeHighlight.SELECTED
    game.hint?.from == tube -> TubeHighlight.HINT_FROM
    game.hint?.to == tube -> TubeHighlight.HINT_TO
    else -> TubeHighlight.NONE
}

/** The headroom over the top row, in tube widths. */
private const val LIFT_ROOM = 0.5f
